window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[262]={"id":"262","numero":262,"titre":"Néphropathies tubulo-interstitielles","objectifs":[{"id":"262-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique d’une néphropathie interstitielle chronique (NIC)","contenu":"<div class=\"obj-callout success\"><strong>À comprendre.</strong> <span class=\"kw-clinique\">Les</span> néphropathies tubulaires chroniques s'accompagnent <strong>toujours</strong> d'un retentissement interstitiel, et les néphropathies interstitielles chroniques d'un retentissement tubulaire : on les regroupe sous le nom de <span class=\"kw-def\">néphropathies tubulo-interstitielles chroniques (NIC)</span>. Elles se caractérisent par un tableau rénal qui traduit la <strong>dysfonction tubulaire</strong> et par une <span class=\"kw-clinique\">évolution relativement lente</span>.</div>\n      <p><strong>Présentation clinique</strong> — la NIC est souvent <span class=\"kw-clinique\">longtemps asymptomatique</span> ; <span class=\"kw-clinique\">les</span> signes cliniques sont pauvres et tardifs, contrastant avec les autres néphropathies chroniques.</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>HTA</strong></span></td>\n            <td><span class=\"kw-clinique\">tardive</span> — apparaît <strong>plus tardivement</strong> que dans <span class=\"kw-clinique\">les</span> autres néphropathies chroniques (volontiers aux <span class=\"kw-chiffre\">stades 4-5</span> de l'IRC)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Nécrose papillaire</strong></span></td>\n            <td><span class=\"kw-clinique\">hématurie macroscopique isolée</span>, ou <span class=\"kw-clinique\">colique néphrétique</span> associée</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Contrairement aux glomérulopathies, la NIC ne se manifeste <strong>ni par un <span class=\"kw-clinique\">syndrome néphrotique</span> ni par une <span class=\"kw-bio\">hématurie</span> macroscopique récidivante d'emblée</strong> : c'est l'association <span class=\"kw-bio\">IRC lentement progressive</span> + <span class=\"kw-bio\">anomalies tubulaires</span> + <span class=\"kw-bio\">leucocyturie aseptique</span> qui doit la faire évoquer (<em>cf. signes biologiques, objectif suivant</em>).</div>\n\n      <div class=\"obj-subsection\" style=\"border-left: 3px solid var(--warn); padding-left: 14px; margin-top: 18px;\">\n        <p style=\"margin:0 0 8px\"><strong>Formes aiguës — à distinguer (rappel)</strong> · <span class=\"kw-clinique\">les</span> atteintes tubulo-interstitielles <span class=\"kw-clinique\">aiguës</span> ont une présentation et un <span class=\"kw-def\">pronostic</span> différents de la NIC.</p>\n        <table >\n          <thead><tr><th>Entité aiguë</th><th>Mécanisme & présentation</th></tr></thead>\n          <tbody>\n            <tr>\n              <td><span class=\"kw-etio\"><strong>NTA</strong></span><br>(<span class=\"kw-clinique\">nécrose</span> tubulaire aiguë)</td>\n              <td>atteinte prédominante = <span class=\"kw-alerte\">nécrose des cellules tubulaires</span> (mécanismes <span class=\"kw-clinique\">ischémique</span> — <span class=\"kw-alerte\">état de choc</span> — et/ou <span class=\"kw-clinique\">toxique</span> souvent associés)<br><strong>Tableau :</strong> <span class=\"kw-clinique\">IRA « nue »</span> — pas d'<span class=\"kw-etio\">HTA</span>, pas d'<span class=\"kw-clinique\">œdème</span>, <span class=\"kw-bio\">protéinurie</span> &lt;<span class=\"kw-chiffre\"> 1 g</span>/j, pas d'<span class=\"kw-bio\">hématurie</span> ni de <span class=\"kw-bio\">leucocyturie</span> ; profil urinaire <span class=\"kw-bio\">organique</span> ; PBR non nécessaire</td>\n            </tr>\n            <tr>\n              <td><span class=\"kw-etio\"><strong>NIA</strong></span><br>(néphrite interstitielle aiguë)</td>\n              <td>atteinte prédominante = <span class=\"kw-alerte\">œdème interstitiel</span> + <span class=\"kw-alerte\">infiltration interstitielle</span> (<span class=\"kw-bio\">leucocytes</span>)<br><strong>Tableau :</strong> diurèse souvent conservée (anurie possible), <span class=\"kw-bio\">hématurie</span> inconstante, <span class=\"kw-bio\">leucocyturie</span> ± <span class=\"kw-bio\">éosinophilurie</span>, <span class=\"kw-bio\">protéinurie</span> tubulaire &lt;<span class=\"kw-chiffre\"> 1 g/L</span> (α/β-globulines, <strong>pas d'<span class=\"kw-bio\">albumine</span></strong>) ; <span class=\"kw-clinique\">pas d'HTA ni d'œdèmes</span></td>\n            </tr>\n          </tbody>\n        </table>\n        <table  style=\"margin-top:10px\">\n          <thead><tr><th>NIA médicamenteuse</th><th>Atteinte <span class=\"kw-etio\">toxique</span></th><th>Atteinte immuno-<span class=\"kw-etio\">allergique</span></th></tr></thead>\n          <tbody>\n            <tr>\n              <td><span class=\"kw-def\"><strong>Médicaments</strong></span></td>\n              <td><span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">antalgiques</span>, anticalcineurines (<span class=\"kw-ttt\">ciclosporine, tacrolimus</span>), <span class=\"kw-ttt\">ténofovir</span></td>\n              <td><span class=\"kw-ttt\">sulfamides, β-lactamines, fluoroquinolones, rifampicine</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IPP</span>, certaines immunothérapies</td>\n            </tr>\n            <tr>\n              <td><span class=\"kw-def\"><strong>Dose</strong></span></td>\n              <td>relation <strong>directe</strong> dose ↔ toxicité</td>\n              <td><strong>indépendante de la dose</strong> ; récidive à la ré-administration</td>\n            </tr>\n            <tr>\n              <td><span class=\"kw-def\"><strong>Extra-rénal</strong></span></td>\n              <td>absent</td>\n              <td><span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">adénopathies</span>, <span class=\"kw-clinique\">prurit</span>/rash, arthralgies, cytolyse hépatique — au maximum <span class=\"kw-alerte\">DRESS</span> ⚠️</td>\n            </tr>\n            <tr>\n              <td><span class=\"kw-def\"><strong>Éosinophiles</strong></span></td>\n              <td>pas d'hyperéosinophilie</td>\n              <td>éosinophilie, <span class=\"kw-bio\">éosinophilurie</span> (inconstante, <strong>pathognomonique dans ce contexte</strong>)</td>\n            </tr>\n            <tr>\n              <td><span class=\"kw-def\"><strong>PEC</strong></span></td>\n              <td>arrêt du médicament</td>\n              <td>arrêt <strong>définitif</strong> du médicament ± <span class=\"kw-ttt\">corticothérapie</span> (si <span class=\"kw-alerte\">DRESS</span>) ; séquelles fréquentes</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-bio\">Protéinurie</span>, <span class=\"kw-clinique\">syndrome néphrotique</span> · 260 — <span class=\"kw-bio\">Hématurie</span> · 264 — IRC · 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë</em></p>","frequence":0},{"id":"262-2","rang":"A","rubrique":"Examens complémentaires","titre":"Reconnaître les signes biologiques évocateurs de NIC","contenu":"<p>Le diagnostic de NIC est <strong><span class=\"kw-ttt\">biologique</span> et radiologique</strong> avant tout : la PBR est rarement réalisée. Trois grands axes — <span class=\"kw-bio\">sang</span>, <span class=\"kw-bio\">urines</span>, <span class=\"kw-imagerie\">imagerie</span> — orientent vers l'origine tubulo-interstitielle.</p>\n      <table >\n        <thead><tr><th>Compartiment</th><th>Signes évocateurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Sang</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">Insuffisance rénale chronique</span> d'<span class=\"kw-clinique\">évolution</span> <strong>très lente</strong> (<span class=\"kw-chiffre\">↓ 1 à 3 mL/min/an</span>) : peut être la <strong>seule anomalie <span class=\"kw-ttt\">biologique</span></strong></li>\n                <li><span class=\"kw-bio\">Acidose tubulaire</span> (hyperchlorémique = à <strong><span class=\"kw-bio\">trou anionique</span> normal</strong>) : proximale, distale ou hyperkaliémique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Urines</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">Leucocyturie aseptique</span> ++ (sans germe) : évocatrice mais <span class=\"kw-clinique\">inconstante</span> (dépend de la cause)</li>\n                <li><strong>Absence d'<span class=\"kw-bio\">hématurie</span></strong> le plus souvent, ou <span class=\"kw-bio\">hématurie</span> microscopique</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <p style=\"margin:0 0 6px\"><strong>Altération des fonctions tubulaires (4)</strong> — la signature de la NIC.</p>\n        <ul style=\"margin:0\">\n          <li><span class=\"kw-clinique\">Polyurie</span></li>\n          <li><span class=\"kw-clinique\">Natriurèse obligatoire</span> (entraîne une <strong>perte de sel</strong>)</li>\n          <li><span class=\"kw-bio\">Acidose tubulaire</span> hyperchlorémique (TA normal) : proximale, distale ou hyperkaliémique</li>\n          <li><span class=\"kw-bio\">Protéinurie tubulaire caractéristique</span> :\n            <ul>\n              <li><strong>Faible débit</strong> : <span class=\"kw-chiffre\">&lt; 1 g/24 h</span> (rapport <span class=\"kw-bio\">protéinurie</span>/créatininurie &lt;<span class=\"kw-chiffre\"> 1 g</span>/g ou &lt;<span class=\"kw-chiffre\"> 100 mg</span>/mmol)</li>\n              <li><strong>Bas poids moléculaire</strong> : <span class=\"kw-chiffre\">&lt; 50 % d'albumine</span> à l'électrophorèse — β2-microglobuline, RBP (<em>retinol binding protein</em>) ; non recherchées en routine</li>\n            </ul>\n          </li>\n        </ul>\n      </div>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Résultats évocateurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Échographie</strong></span></td>\n            <td>\n              <ul>\n                <li>Reins de <span class=\"kw-radio\">taille diminuée</span></li>\n                <li>Reins <span class=\"kw-radio\">bosselés avec encoches</span> ; reins de <span class=\"kw-radio\">taille asymétrique</span></li>\n                <li><span class=\"kw-radio\">Réduction de l'épaisseur corticale</span></li>\n                <li><span class=\"kw-radio\">Calcifications intra-rénales</span> (évoquant une néphrocalcinose)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Histologie</strong></span><br>(PBR <span class=\"kw-clinique\">rarement réalisée</span>)</td>\n            <td>\n              <ul>\n                <li><strong>PBR habituellement non réalisée</strong> (petite taille des reins + contexte clinique souvent suffisant)</li>\n                <li><span class=\"kw-alerte\">Fibrose interstitielle</span> : se développe progressivement</li>\n                <li>Lésions des cellules tubulaires : souffrance cellulaire, <span class=\"kw-clinique\">atrophie</span></li>\n                <li><span class=\"kw-ttt\">Infiltration</span> interstitielle par cellules <span class=\"kw-clinique\">mononucléées</span>, parfois <span class=\"kw-clinique\">granulomes</span> (<span class=\"kw-clinique\">sarcoïdose</span>)</li>\n                <li><strong>Glomérules & vaisseaux</strong> : <span class=\"kw-clinique\">préservés</span> aux stades initiaux → <span class=\"kw-alerte\">lésions vasculaires + glomérulosclérose</span> aux stades avancés</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le couple <span class=\"kw-bio\">protéinurie tubulaire</span> (<strong>faible débit + &lt;<span class=\"kw-chiffre\"> 50 %</span> d'<span class=\"kw-bio\">albumine</span></strong>) + <span class=\"kw-bio\">leucocyturie aseptique</span> est le marqueur <span class=\"kw-ttt\">biologique</span> le plus évocateur de NIC. <span class=\"kw-clinique\">Les</span> signes histologiques (fibrose, atrophie tubulaire) sont <strong>non spécifiques de la cause</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-bio\">Protéinurie</span> tubulaire <span class=\"kw-bio\">vs</span> glomérulaire · 264 — IRC · 267 — Troubles de l'équilibre acido-basique</em></p>","frequence":1},{"id":"262-3","rang":"A","rubrique":"Étiologies","titre":"Connaître les principaux mécanismes de NIC","contenu":"<p><span class=\"kw-clinique\">Les</span> NIC relèvent de mécanismes <strong>variés</strong> dont le point commun est une agression chronique du <span class=\"kw-def\">tubule et de l'interstitium</span> aboutissant à la <span class=\"kw-alerte\">fibrose interstitielle</span> et à l'<span class=\"kw-clinique\">atrophie tubulaire</span>. On les classe par grand mécanisme étiologique.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Principales causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Urologiques</strong></span></td>\n            <td>uropathie obstructive ou malformative · reflux vésico-urétéral · lithiase/oxalose/cystinose · <span class=\"kw-clinique\">infection urinaire</span> <span class=\"kw-clinique\">(détaillées objectif suivant)</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Médicaments</strong></span></td>\n            <td><span class=\"kw-ttt\">cisplatine ++</span>, <span class=\"kw-ttt\">lithium</span>, analgésiques/<span class=\"kw-ttt\">aspirine</span>/<span class=\"kw-ttt\">AINS</span> au long cours, anticalcineurines <span class=\"kw-clinique\">(détaillées objectif suivant)</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Toxiques</strong></span></td>\n            <td><span class=\"kw-ttt\">plomb</span>, <span class=\"kw-ttt\">cadmium</span>, <span class=\"kw-clinique\">irradiation</span>, <span class=\"kw-etio\">herbes chinoises</span> / néphropathie endémique des Balkans</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Génétiques</strong></span></td>\n            <td>maladies génétiques avec ou sans kystes (mutation de l'<span class=\"kw-bio\">uromoduline</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Dysimmunitaires</strong></span></td>\n            <td>syndrome de <span class=\"kw-etio\">Sjögren</span> · <span class=\"kw-etio\">sarcoïdose</span> · <span class=\"kw-clinique\">lupus</span>, sclérodermie · <span class=\"kw-etio\">NITU</span> (néphrite interstitielle et tubulaire avec uvéite)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Métaboliques</strong></span></td>\n            <td>néphrocalcinose (hypercalcémie chronique) · hypokaliémie chronique · hyperuricémie/goutte <span class=\"kw-clinique\">(détaillées objectif suivant)</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Hématologiques</strong></span></td>\n            <td>Ig monoclonale (avec ou sans myélome) · <span class=\"kw-etio\">drépanocytose</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Infectieux</strong></span></td>\n            <td><span class=\"kw-etio\">tuberculose</span> · <span class=\"kw-clinique\">pyélonéphrite</span> xanthogranulomateuse</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Autres</strong></span></td>\n            <td>amylose · cicatrisation d'une NTIA (médicamenteuse, infectieuse)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <p style=\"margin:0 0 6px\"><strong>Focus — néphropathie aux herbes chinoises (acide aristolochique)</strong></p>\n        <ul style=\"margin:0\">\n          <li>Forme <span class=\"kw-alerte\">rapidement progressive</span>, secondaire à la prise d'herbes chinoises dans un but d'<span class=\"kw-clinique\">amaigrissement</span></li>\n          <li>Néphrotoxine = <span class=\"kw-ttt\">acide aristolochique</span> (dérivé d'<em>Aristolochia fangchi</em>, retiré du marché)</li>\n          <li><span class=\"kw-clinique\">Évolution</span> sévère <strong>malgré l'arrêt</strong> : progresse vers une <span class=\"kw-alerte\">IRC terminale en &lt; 2 ans</span></li>\n          <li>Favorise la survenue de <span class=\"kw-alerte\">tumeurs urothéliales</span></li>\n          <li>Même agent <span class=\"kw-etio\">toxique</span> impliqué dans la <span class=\"kw-clinique\">néphropathie endémique des Balkans</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <p style=\"margin:0 0 6px\"><strong><span class=\"kw-clinique\">Évolution</span> & principes de prise en charge</strong></p>\n        <ul style=\"margin:0\">\n          <li><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-clinique\">lentement progressive</span> ; traitement reposant surtout sur <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">mesures symptomatiques</span> de l'IRC</li>\n          <li>Le <span class=\"kw-ttt\">traitement étiologique</span> doit toujours être envisagé — mais si <span class=\"kw-clinique\">les</span> lésions fibreuses sont étendues, les <strong>séquelles sont la règle</strong></li>\n          <li>Cause obstructive : la levée de l'obstacle chronique n'est bénéfique que si l'obstacle est <strong>récent</strong> avec un cortex rénal d'épaisseur conservée</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — IRC · 261 — Néphropathies glomérulaires · 348 — IRA · obj. Rang B (causes détaillées) ci-dessous</em></p>","frequence":0},{"id":"262-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales causes des NIC urologiques, médicamenteuses et métaboliques","contenu":"<p>Trois familles de causes à connaître en détail (Rang B) — elles représentent <span class=\"kw-clinique\">les</span> NIC les plus fréquentes en pratique.</p>\n\n      <div class=\"obj-callout success\">\n        <p style=\"margin:0 0 6px\"><span class=\"kw-etio\"><strong>① Causes urologiques</strong></span></p>\n        <ul style=\"margin:0\">\n          <li><span class=\"kw-clinique\">Uropathie obstructive</span> ou <span class=\"kw-clinique\">malformative</span></li>\n          <li><span class=\"kw-clinique\">Reflux vésico-urétéral</span> — parfois compliqué d'une <span class=\"kw-alerte\">HSF secondaire</span> (hyalinose segmentaire et focale)</li>\n          <li><span class=\"kw-clinique\">Lithiase</span> / oxalose / cystinose</li>\n          <li>L'<strong><span class=\"kw-clinique\">infection urinaire</span></strong> joue un rôle important (entretien des lésions)</li>\n        </ul>\n      </div>\n\n      <div class=\"obj-callout success\">\n        <p style=\"margin:0 0 6px\"><span class=\"kw-etio\"><strong>② Causes médicamenteuses</strong></span> (au long cours)</p>\n        <ul style=\"margin:0\">\n          <li><span class=\"kw-ttt\">Cisplatine ++</span></li>\n          <li><span class=\"kw-ttt\">Lithium</span></li>\n          <li><span class=\"kw-ttt\">Analgésiques, aspirine, AINS</span> — prise prolongée</li>\n          <li><span class=\"kw-ttt\">Anticalcineurines</span> : <span class=\"kw-ttt\">ciclosporine</span> A, <span class=\"kw-ttt\">tacrolimus</span></li>\n        </ul>\n      </div>\n\n      <div class=\"obj-callout success\">\n        <p style=\"margin:0 0 6px\"><span class=\"kw-etio\"><strong>③ Causes métaboliques</strong></span></p>\n        <ul style=\"margin:0\">\n          <li><span class=\"kw-bio\">Néphrocalcinose</span> — par <strong>hypercalcémie chronique</strong></li>\n          <li><span class=\"kw-bio\">Hypokaliémie chronique</span></li>\n          <li><span class=\"kw-bio\">Hyperuricémie</span> / goutte</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Réflexe étiologique devant une NIC : <strong>interrogatoire <span class=\"kw-etio\">médicamenteux</span></strong> exhaustif (<span class=\"kw-ttt\">AINS</span>/<span class=\"kw-ttt\">antalgiques</span> au long cours, <span class=\"kw-ttt\">lithium</span>, cisplatine, anticalcineurines), <strong>imagerie de l'arbre urinaire</strong> (obstacle, reflux, lithiase) et <strong>bilan métabolique</strong> (<span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">kaliémie</span>, <span class=\"kw-bio\">uricémie</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 267 — Désordres hydro-électrolytiques (hypokaliémie, hypercalcémie) · 268 — Hypercalcémie · 265 — Lithiase urinaire</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>NIA immuno-<span class=\"kw-etio\">allergique</span> <span class=\"q\">— <span class=\"kw-alerte\">DRESS</span> au maximum</span></strong></p><p><span class=\"kw-ttt\">Arrêt définitif</span> du médicament ± <span class=\"kw-ttt\">corticothérapie</span> si <span class=\"kw-alerte\">DRESS</span></p><ul><li>Réaction <span class=\"kw-clinique\">immuno-allergique</span> au médicament, <strong>indépendante de la dose</strong> ; au maximum tableau de <span class=\"kw-alerte\">DRESS</span></li><li><span class=\"kw-clinique\">Récidive</span> des mêmes symptômes à toute <span class=\"kw-clinique\">ré-administration</span></li></ul><p><strong>NIA infectieuse sévère <span class=\"q\">— surtout si obstacle sur la voie excrétrice</span></strong></p><p><span class=\"kw-imagerie\">TDM injectée</span> (ou <span class=\"kw-imagerie\">IRM</span>) : foyers de <span class=\"kw-clinique\">PNA</span>, micro-<span class=\"kw-clinique\">abcès</span>, <span class=\"kw-clinique\">abcès</span> ou <span class=\"kw-alerte\">phlegmon péri-néphrétique</span></p><ul><li>Peut être <span class=\"kw-alerte\">très sévère</span> : tableau de <span class=\"kw-alerte\">choc septique</span>, surtout en cas d'<span class=\"kw-clinique\">obstacle sur la voie excrétrice</span></li><li>Étiologies : infections <span class=\"kw-clinique\">ascendantes</span> (<span class=\"kw-etio\">pyélonéphrite aiguë</span>), <span class=\"kw-clinique\">hématogènes</span> (<span class=\"kw-clinique\">septicémie</span>), <span class=\"kw-etio\">leptospirose</span>, fièvres hémorragiques virales</li></ul><p><strong>NIC obstructive <span class=\"q\">— fenêtre de levée de l'obstacle</span></strong></p><p>Au-delà (<span class=\"kw-alerte\">fibrose étendue</span>), <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">séquelles sont la règle</span></p><ul><li>La <span class=\"kw-ttt\">levée de l'obstacle</span> chronique n'est bénéfique que si l'obstacle est <strong>relativement récent</strong>, avec un <span class=\"kw-imagerie\">cortex rénal d'épaisseur conservée</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">DRESS</span> sur NIA immuno-<span class=\"kw-etio\">allergique</span> : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">adénopathies</span>, <span class=\"kw-clinique\">prurit / rash</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-bio\">cytolyse hépatique</span></li><li><span class=\"kw-bio\">Éosinophilurie</span> (inconstante mais <strong>pathognomonique</strong> dans le contexte immuno-<span class=\"kw-etio\">allergique</span>)</li><li><span class=\"kw-alerte\">Choc septique</span> d'une NIA infectieuse, surtout sur <span class=\"kw-clinique\">obstacle</span> de la voie excrétrice</li><li>Néphropathie aux <span class=\"kw-etio\">herbes chinoises</span> (<span class=\"kw-ttt\">acide aristolochique</span>) : <span class=\"kw-alerte\">IRC terminale en &lt; 2 ans</span> malgré l'arrêt + <span class=\"kw-alerte\">tumeurs urothéliales</span></li><li><span class=\"kw-alerte\">Fibrose interstitielle étendue</span> : <span class=\"kw-clinique\">les</span> <strong>séquelles deviennent la règle</strong> (traitement étiologique trop tardif)</li></ul>","principes":"<p>NIC d'<span class=\"kw-clinique\">évolution</span> <span class=\"kw-clinique\">lentement progressive</span> : le traitement repose surtout sur <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">mesures symptomatiques</span> de l'<span class=\"kw-bio\">IRC</span>. Le <span class=\"kw-ttt\">traitement étiologique</span> doit <strong>toujours</strong> être envisagé — mais si les <span class=\"kw-alerte\">lésions fibreuses sont étendues</span>, les séquelles sont la règle.</p><p><strong>Réflexe étiologique devant une NIC</strong></p><ul><li><strong>Interrogatoire <span class=\"kw-etio\">médicamenteux</span></strong> exhaustif : <span class=\"kw-ttt\">AINS / antalgiques</span> au long cours, <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">cisplatine</span>, <span class=\"kw-ttt\">anticalcineurines</span></li><li><span class=\"kw-imagerie\">Imagerie de l'arbre urinaire</span> : obstacle, reflux, lithiase</li><li><span class=\"kw-bio\">Bilan métabolique</span> : <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">kaliémie</span>, <span class=\"kw-bio\">uricémie</span></li></ul><p><strong>NIA médicamenteuse <span class=\"kw-etio\">toxique</span></strong></p><ul><li>Relation <strong>directe</strong> entre dose et toxicité</li><li><span class=\"kw-ttt\">Arrêt du médicament</span> en cause</li><li><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-clinique\">favorable</span>, sauf exception (<span class=\"kw-ttt\">cisplatine</span>)</li></ul><p><strong>NIA médicamenteuse immuno-<span class=\"kw-etio\">allergique</span></strong></p><p><span class=\"kw-ci\">Ne jamais ré-administrer le médicament</span> (récidive assurée)</p><ul><li><strong>Indépendante de la dose</strong> ; <span class=\"kw-clinique\">récidive</span> à la ré-administration</li><li><span class=\"kw-ttt\">Arrêt définitif</span> du médicament ± <span class=\"kw-ttt\">corticothérapie</span> si <span class=\"kw-alerte\">DRESS</span></li><li><span class=\"kw-alerte\">Séquelles fréquentes</span> (IRC avec fibrose interstitielle + atrophie tubulaire)</li></ul><p><strong>NIC obstructive</strong></p><ul><li><span class=\"kw-ttt\">Levée de l'obstacle</span> — bénéfique seulement si obstacle <strong>récent</strong> avec <span class=\"kw-imagerie\">cortex conservé</span></li></ul><p><strong>Néphropathie aux herbes chinoises <span class=\"q\">— acide aristolochique</span></strong></p><ul><li>Arrêt de la consommation — mais <span class=\"kw-alerte\">évolution sévère malgré l'arrêt</span> (<span class=\"kw-alerte\">IRC terminale en &lt; 2 ans</span>)</li><li><span class=\"kw-def\">Surveillance</span> du risque de <span class=\"kw-alerte\">tumeurs urothéliales</span></li></ul>","suivi":"<p><strong>Fonction rénale :</strong> l'<span class=\"kw-bio\">IRC</span> de la NIC évolue <strong>très lentement</strong> (<span class=\"kw-chiffre\">↓ 1 à 3 mL/min/an</span>) et peut être la <strong>seule anomalie <span class=\"kw-ttt\">biologique</span></strong> — <span class=\"kw-def\">surveillance</span> prolongée de la fonction rénale.<br><strong>NIA immuno-<span class=\"kw-etio\">allergique</span> :</strong> <span class=\"kw-alerte\">séquelles fréquentes</span> (IRC avec <span class=\"kw-alerte\">fibrose interstitielle</span> et <span class=\"kw-clinique\">atrophie tubulaire</span>).<br><strong>Herbes chinoises (acide aristolochique) :</strong> <span class=\"kw-def\">surveillance</span> du risque de <span class=\"kw-alerte\">tumeurs urothéliales</span>.</p>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique26","label":"Collège CUEN — Néphropathies tubulo-interstitielles"}],"cards":[]};